{
  "name": "超高频量子分析仪（UHFQA）",
  "name_en": "UHF Quantum Analyzer (UHFQA)",
  "manufacturer": "Zurich Instruments",
  "description": "这是一台用于量子实验的物理仪器，面向量子比特读出与控制场景。它提供量子分析通道、任意波形发生、序列器程序加载、波形存储器访问、积分权重配置，以及与 PQSC 配合的 QCCS 同步设置。",
  "description_en": "This is a physical instrument for quantum experiments, used for qubit readout and control workflows. It provides quantum analyzer channels, arbitrary waveform generation, sequencer program loading, waveform memory access, integration weight configuration, and QCCS synchronization settings for operation with a PQSC.",
  "actions": [
    {
      "action_name": "auto-enable_qccs_mode",
      "description": "配置仪器进入 QCCS 模式，以便与 PQSC 正确连接和同步。",
      "description_en": "Configure the instrument for QCCS mode so it can connect to and synchronize with a PQSC."
    },
    {
      "action_name": "auto-check_status",
      "description": "检查命令表或相关上传对象在仪器上的状态。",
      "description_en": "Check the status of the command table or related uploaded object on the instrument."
    },
    {
      "action_name": "auto-load_validation_schema",
      "description": "加载用于校验命令表的验证模式。",
      "description_en": "Load the validation schema used to validate a command table."
    },
    {
      "action_name": "auto-upload_to_device",
      "description": "将命令表上传到仪器。",
      "description_en": "Upload a command table to the instrument."
    },
    {
      "action_name": "auto-load_from_device",
      "description": "从仪器读取命令表。",
      "description_en": "Load a command table from the instrument."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用 AWG 序列器运行。",
      "description_en": "Enable the AWG sequencer."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待序列器或相关 AWG 操作完成。",
      "description_en": "Wait until the sequencer or related AWG operation is complete."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译序列器程序以供 AWG 执行。",
      "description_en": "Compile a sequencer program for AWG execution."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将序列器程序加载到 AWG。",
      "description_en": "Load a sequencer program onto the AWG."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "向 AWG 波形存储器写入波形数据。",
      "description_en": "Write waveform data to the AWG waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从 AWG 波形存储器读取波形数据。",
      "description_en": "Read waveform data from the AWG waveform memory."
    },
    {
      "action_name": "auto-write_integration_weights",
      "description": "写入量子分析积分权重，用于读出信号积分处理。",
      "description_en": "Write integration weights for quantum analyzer readout signal integration."
    },
    {
      "action_name": "auto-crosstalk_matrix",
      "description": "获取或设置串扰补偿矩阵。",
      "description_en": "Get or set the crosstalk compensation matrix."
    },
    {
      "action_name": "auto-adjusted_delay",
      "description": "获取或设置调整后的延迟参数。",
      "description_en": "Get or set the adjusted delay parameter."
    }
  ],
  "tag_hints": [
    "qubit readout",
    "Zurich Instruments UHFQA",
    "quantum analyzer",
    "AWG sequencer",
    "integration weights",
    "QCCS/PQSC synchronization",
    "waveform memory"
  ]
}

